 function accounts(){
  const map=new Map(workspaceCapture.accounts.filter(a=>a.OwnerId===fresh().ownerId).map(a=>[a.Id,a]));
  if(state.style==='atlas'){const extra=state.persona==='retail'?[...atlasData.datasets.retention,...atlasData.datasets.stressWatch,...retailData.datasets.heatmap,...retailData.datasets.browsing,...retailCohortData.profiles,...retailPriorityData.datasets.who.map(r=>({account:r.account_id,name:r.name})),...retailPriorityData.datasets.liquidity.map(r=>({account:r.person_account_id__c,name:r.name})),...retailPriorityData.datasets.inflows.map(r=>({account:r.account_id,name:r.name}))]:state.persona==='wealth'?[...atlasData.datasets.digital,...atlasData.datasets.reviews]:[];for(const r of extra){const a=atlasData.accounts.find(a=>a.Id===r.account)||{Id:r.account,Name:r.name,captureLink:true};if(a.Name&&!map.has(a.Id))map.set(a.Id,a);}}
  if(state.style==='atlas'&&state.persona==='retail'){for(const r of [...retailBusinessCore.offers(retailBusinessData),...retailBusinessData.datasets.intros.map(r=>({account:r.src_id,name:r.referrer})),...['equity','mortgage','investing'].flatMap(k=>retailBusinessData.datasets[k].map(r=>({account:r.account_id,name:r.name})))])if(r.account&&r.name&&!map.has(r.account))map.set(r.account,{Id:r.account,Name:r.name,captureLink:true});}
  if(state.style==='atlas'&&state.persona==='retail')for(const a of retailCustomerData.crm.account)map.set(a.Id,{...map.get(a.Id),...a});
  if(state.style==='atlas'&&state.persona==='retail')for(const a of retailWatchData.accounts.filter(a=>a.OwnerId===retailWatchData.ownerId))map.set(a.Id,{...map.get(a.Id),...a});
  for(const r of [...crm().opportunities,...crm().cases,...crm().tasks]){const id=relatedId(r);if(id&&!map.has(id))map.set(id,{Id:id,Name:r.Account.Name,captureLink:true});}
  for(const e of fresh().lifeEvents){const id=e.PrimaryPerson?.AccountId;if(id&&!map.has(id))map.set(id,{Id:id,Name:e.PrimaryPerson.Account?.Name||e.PrimaryPerson.Name});}
  for(const a of atlasPersona()?.accounts?.()||[])if(a.Id&&a.Name)map.set(a.Id,{...map.get(a.Id),...a});
  return [...map.values()].sort((a,b)=>{
   const ai=signals[state.persona].findIndex(x=>x.id===a.Id),bi=signals[state.persona].findIndex(x=>x.id===b.Id);
   return (ai<0?99:ai)-(bi<0?99:bi)||a.Name.localeCompare(b.Name)||a.Id.localeCompare(b.Id);
  });
 }
